          "claim": "All 1532 auth login server spans return 500 and their UserController.getToken spans error."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.service_name, c.span_name, c.attr_span_kind, c.attr_http_response_status_code code, count(*) n, sum(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) errs FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-auth-service' GROUP BY 1,2,3,4",
